/**
 * Firefly Mac bridge: a tiny launchd service on the Mac host that lets the agent
 * run macOS Shortcuts, and nothing else.
 *
 * - Listens on 127.0.0.1 only (Docker reaches it as host.docker.internal).
 * - Bearer token from a file (generated by bridge/install.sh).
 * - Its only action is `shortcuts run <name>` for shortcuts that are both in
 *   the allowlist (config.json) and in the Shortcuts folder named "Agent".
 * - No AppleScript, no shell: execFile with a fixed argument vector.
 * - Ships with an empty allowlist, so it rejects every call until you add names.
 *
 *   node bridge/server.ts            (Node 22.18+, type stripping)
 */
import { execFile } from "node:child_process";
import { timingSafeEqual } from "node:crypto";
import { readFileSync } from "node:fs";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import http from "node:http";
import os from "node:os";
import path from "node:path";

const HOME = os.homedir();
const DIR = process.env.FIREFLY_BRIDGE_DIR ?? path.join(HOME, "Library", "Application Support", "Firefly");
const PORT = Number(process.env.PORT ?? 7072);
const HOST = process.env.HOST ?? "127.0.0.1";
const FOLDER = process.env.SHORTCUTS_FOLDER ?? "Agent";
const SHORTCUTS = process.env.SHORTCUTS_BIN ?? "/usr/bin/shortcuts";

interface BridgeConfig {
  /** Exact shortcut names the agent may run. Empty = every call is rejected. */
  allowlist: string[];
}

function readToken(): string {
  const t = readFileSync(path.join(DIR, "bridge.token"), "utf8").trim();
  if (t.length < 24) throw new Error("bridge.token must be at least 24 characters");
  return t;
}

/** Re-read on every call so edits apply without a restart. */
function readConfig(): BridgeConfig {
  try {
    const raw = JSON.parse(readFileSync(path.join(DIR, "config.json"), "utf8")) as Partial<BridgeConfig>;
    return { allowlist: Array.isArray(raw.allowlist) ? raw.allowlist.filter((x): x is string => typeof x === "string") : [] };
  } catch {
    return { allowlist: [] };
  }
}

const TOKEN = readToken();

function run(args: string[], timeoutMs: number): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((resolve) => {
    execFile(SHORTCUTS, args, { timeout: timeoutMs, maxBuffer: 1024 * 1024, shell: false }, (err, stdout, stderr) => {
      const code = err ? (typeof (err as { code?: unknown }).code === "number" ? ((err as { code: number }).code) : 1) : 0;
      resolve({ code, stdout: String(stdout), stderr: String(stderr) });
    });
  });
}

async function shortcutsInFolder(): Promise<Set<string>> {
  const r = await run(["list", "--folder-name", FOLDER], 15_000);
  if (r.code !== 0) throw new Error(`could not list the "${FOLDER}" Shortcuts folder`);
  return new Set(r.stdout.split("\n").map((s) => s.trim()).filter(Boolean));
}

function send(res: http.ServerResponse, status: number, body: unknown): void {
  const text = JSON.stringify(body);
  res.writeHead(status, { "content-type": "application/json", "content-length": Buffer.byteLength(text) });
  res.end(text);
}

function authorized(header: string | undefined): boolean {
  if (!header?.startsWith("Bearer ")) return false;
  const a = Buffer.from(header.slice(7));
  const b = Buffer.from(TOKEN);
  return a.length === b.length && timingSafeEqual(a, b);
}

const server = http.createServer(async (req, res) => {
  try {
    if (req.method === "GET" && req.url === "/health") return send(res, 200, { ok: true, allowlisted: readConfig().allowlist.length });
    if (!authorized(req.headers.authorization)) return send(res, 401, { error: "unauthorized" });
    if (req.method !== "POST" || req.url !== "/shortcut") return send(res, 404, { error: "the only action is POST /shortcut" });

    const chunks: Buffer[] = [];
    for await (const c of req) {
      chunks.push(c as Buffer);
      if (chunks.reduce((n, b) => n + b.length, 0) > 64 * 1024) return send(res, 413, { error: "too large" });
    }
    const body = JSON.parse(Buffer.concat(chunks).toString() || "{}") as { name?: unknown; input?: unknown };
    const name = typeof body.name === "string" ? body.name : "";

    const { allowlist } = readConfig();
    if (allowlist.length === 0) return send(res, 403, { error: "the bridge allowlist is empty; no shortcuts may run" });
    if (!allowlist.includes(name)) return send(res, 403, { error: `"${name}" is not on the bridge allowlist` });
    if (!(await shortcutsInFolder()).has(name)) return send(res, 403, { error: `"${name}" is not in the "${FOLDER}" Shortcuts folder` });

    const args = ["run", name];
    let tmp: string | undefined;
    if (typeof body.input === "string" && body.input.length > 0) {
      tmp = await mkdtemp(path.join(os.tmpdir(), "firefly-"));
      await writeFile(path.join(tmp, "input.txt"), body.input.slice(0, 32 * 1024));
      args.push("--input-path", path.join(tmp, "input.txt"));
    }
    const r = await run(args, 120_000).finally(() => (tmp ? rm(tmp, { recursive: true, force: true }) : undefined));
    console.log(JSON.stringify({ msg: "ran shortcut", name, code: r.code, at: new Date().toISOString() }));
    return send(res, r.code === 0 ? 200 : 500, { name, exitCode: r.code, output: r.stdout.slice(0, 8000), error: r.stderr.slice(0, 2000) });
  } catch (err) {
    send(res, 500, { error: (err as Error).message });
  }
});

server.listen(PORT, HOST, () => console.log(JSON.stringify({ msg: "bridge listening", host: HOST, port: PORT, folder: FOLDER })));
